{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify the instance metadata service version, potentially allowing IMDSv1 which is less secure than IMDSv2."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded secret in user data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The API key 'sk-1234567890abcdef' is hardcoded in the user data, potentially exposing sensitive information."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Sensitive information exposure through environment variable",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The DATABASE_PASSWORD is being passed as an environment variable, which could be exposed in the instance's environment."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"web_app\" {\n  name_prefix   = \"automated-employee-onboarding-platform-lt-web-\"\n  image_id      = data.aws_ami.ubuntu.id\n  instance_type = var.instance_type\n  key_name      = var.key_pair_name\n  vpc_security_group_ids = [aws_security_group.web_app.id]\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n  user_data = base64encode(<<-EOF\n              apt-get update\n              apt-get install -y nginx nodejs npm\n              systemctl start nginx\n              systemctl enable nginx\n              EOF\n  )\n  tag_specifications {\n    resource_type = \"instance\"\n  }\n}",
  "fix_summary": "Enabled IMDSv2 by setting http_tokens to 'required' and removed hardcoded secrets from user data."
}
